package com.vandorlabs.physics;
import com.vandorlabs.gear.core.*;
/** Existing shared pose remains an independent scalar-operation-order oracle. */
public final class GearFootProjectionTest {
 private static void guards(){GearFootProjection p=new GearFootProjection();p.prepare(GearMotion.Mode.EXTEND,GearMotion.Direction.NORTH,1,.5,0,0,0,90,0);boolean invalid=false;try{p.prepare(GearMotion.Mode.EXTEND,GearMotion.Direction.NORTH,1,Double.NaN,0,0,0,90,0);}catch(IllegalArgumentException expected){invalid=true;}if(!invalid)throw new AssertionError("invalid phase accepted");try{p.write(0,0,0,new double[3],0);throw new AssertionError("stale pose after refused prepare");}catch(IllegalStateException expected){}p.prepare(GearMotion.Mode.EXTEND,GearMotion.Direction.NORTH,1,0,Double.MAX_VALUE,0,0,90,0);try{p.write(0,Double.MAX_VALUE,0,new double[3],0);throw new AssertionError("nonfinite projection accepted");}catch(IllegalArgumentException expected){}}
 public static void main(String[] args){long checks=0;GearFootProjection scratch=new GearFootProjection();double[] out=new double[3];for(GearMotion.Mode mode:GearMotion.Mode.values())for(GearMotion.Direction direction:GearMotion.Direction.values())for(int height:new int[]{1,3,8})for(double hinge:new double[]{0,17/128D})for(double socket:new double[]{0,13/16D})for(double[] angles:new double[][]{{90,0},{180,-180},{45,-75}})for(int phase=0;phase<=20;phase++){double p=phase/20D;scratch.prepare(mode,direction,height,p,-4.25,hinge,socket,angles[0],angles[1]);GearMotion.Pose oracle=GearMotion.pose(mode,direction,height,p,-4.25,hinge,socket,angles[0],angles[1]);for(int point=0;point<8;point++){double x=(point&1)==0?-.25:3.75,y=(point&2)==0?-8.5:.5625,z=(point&4)==0?-1.75:4.25;GearMotion.Vec expected=oracle.transformFootVertex(x,y,z);scratch.write(x,y,z,out,0);if(Double.doubleToLongBits(expected.x)!=Double.doubleToLongBits(out[0])||Double.doubleToLongBits(expected.y)!=Double.doubleToLongBits(out[1])||Double.doubleToLongBits(expected.z)!=Double.doubleToLongBits(out[2]))throw new AssertionError("Foot projection exact parity mode="+mode+" phase="+p);checks+=3;}}guards();System.out.println("Gear foot scratch PASS exactComponents="+checks);}
}
